"""Make team names navigable and add a concise comprehensive team overview."""
import re
from pathlib import Path

out=Path(__file__).resolve().parent
source=out.parent/'visualization-design-2026-10-06-v04/index-v02.html'
page=source.read_text(encoding='utf-8')
style='''<style>
.teamname{color:inherit;text-decoration:none;min-height:44px;display:inline-flex;align-items:center;font-weight:inherit;border-bottom:1px solid transparent}.teamname:hover{color:#2454c6;border-bottom-color:currentColor}.overviewgrid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:26px 0}.overviewcard{border:1px solid #e0e6ed;border-radius:10px;padding:20px;min-width:0}.overviewcard h3{margin-bottom:12px}.overviewnumber{display:flex;gap:24px;flex-wrap:wrap}.overviewnumber strong{display:block;font-size:25px}.overviewnumber label{font-size:13px;color:#536174}.overviewdate{color:#536174;font-size:12px;display:block}.scheduleitem{display:flex;gap:14px;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e7ebf0}.scheduleitem .mini{font-size:14px}.simplebar{display:grid;grid-template-columns:90px 1fr 50px;gap:12px;align-items:center;margin:12px 0;font-size:14px}.simplebar>span:last-child{text-align:right}.simplebar .track{height:10px}.recorddetails{margin-top:26px;border-top:1px solid #dce2e9;padding-top:18px}.recorddetails>summary{cursor:pointer;min-height:44px;font-size:18px;font-weight:700}.recorddetails[open]>summary{margin-bottom:16px}.overviewcard table td{padding:9px 4px}.overviewcard table .mini{font-size:13px}.overviewcard .chart{height:150px}.overviewcaption{font-size:13px;color:#536174;margin-top:12px}@media(max-width:750px){.overviewgrid{grid-template-columns:1fr}.overviewcard{padding:16px}}
</style>'''
page=page.replace('</head>',style+'</head>')
old="function team(id){return `<span class=\"mini\">${badge(id)}${esc(T[id].name)}</span>`}"
new="function teamName(id){return `<a class=\"teamname\" href=\"#team=${encodeURIComponent(id)}\" data-team=\"${id}\" aria-label=\"${esc(T[id].name)} 종합 정보 보기\">${esc(T[id].name)}</a>`}\nfunction team(id){return `<span class=\"mini\">${badge(id)}${teamName(id)}</span>`}"
assert old in page
page=page.replace(old,new)
page=page.replace('${badge(m.home,true)}${esc(T[m.home].name)}</div>','${badge(m.home,true)}${teamName(m.home)}</div>')
page=page.replace('${esc(T[m.away].name)}${badge(m.away,true)}','${teamName(m.away)}${badge(m.away,true)}')
page=page.replace(' 과거 기록 보기',' 종합 정보 보기')
overview=r'''function overviewRecent(id,ms){return `<div class="tablewrap"><table><thead><tr><th>상대</th><th>결과</th><th>xG</th></tr></thead><tbody>${ms.slice().reverse().map(m=>{let h=m.home===id,f=h?m.hg:m.ag,a=h?m.ag:m.hg;return `<tr><td>${team(h?m.away:m.home)}<small class="overviewdate">${m.date} · ${h?'홈':'원정'}</small></td><td>${f>a?'승':f===a?'무':'패'} ${f}:${a}</td><td>${(h?m.hx:m.ax).toFixed(2)}</td></tr>`}).join('')}</tbody></table></div>`}
function teamOverview(id,ms){let recent=ms.slice(-5),r=calc(id,recent),s=calc(id,ms),next=D.scheduled.filter(m=>(m.home===id||m.away===id)&&m.date>='2026-10-06').sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).slice(0,3),c=colour(id),max=Math.max(1,s.n?s.gf/s.n:0,s.n?s.xg/s.n:0,s.n?s.ga/s.n:0,s.n?s.xga/s.n:0);let trendMax=Math.ceil(Math.max(1,...recent.map(m=>m.home===id?m.hx:m.ax)));let line=recent.map((m,i)=>`${35+i*65},${125-(m.home===id?m.hx:m.ax)/trendMax*100}`).join(' ');
return `<div class="overviewgrid"><section class="overviewcard"><h3>최근 ${r.n}경기</h3>${r.n?`<div class="overviewnumber"><div><strong>${r.p}</strong><label>승점</label></div><div><strong>${r.w}승 ${r.d}무 ${r.l}패</strong><label>최근 성적</label></div></div>${form(id,recent)}${overviewRecent(id,recent)}`:'<p class="muted">선택 시즌의 기록 없음</p>'}</section><section class="overviewcard"><h3>다음 경기</h3>${next.length?next.map(m=>{let h=m.home===id;return `<div class="scheduleitem"><div>${team(h?m.away:m.home)}<small class="overviewdate">${m.date}</small></div><span class="status">${h?'홈':'원정'}</span></div>`}).join(''):'<p class="muted">저장된 예정 경기 없음</p>'}<p class="overviewcaption">2026/27 리그 일정 · 원본 날짜</p></section><section class="overviewcard"><h3>시즌 공격·수비</h3>${s.n?`<div class="overviewnumber"><div><strong>${(s.w/s.n*100).toFixed(1)}%</strong><label>승률</label></div><div><strong>${(s.p/s.n).toFixed(2)}</strong><label>경기당 승점</label></div></div>${[['득점',s.gf/s.n],['기대 득점',s.xg/s.n],['실점',s.ga/s.n],['기대 실점',s.xga/s.n]].map(([label,v])=>`<div class="simplebar"><span>${label}</span><div class="track"><span class="fill" style="display:block;width:${v/max*100}%;background:${c}"></span></div><span>${v.toFixed(2)}</span></div>`).join('')}<span class="muted">경기당 평균 · ${s.n}경기</span>`:'<p class="muted">선택 시즌의 기록 없음</p>'}</section><section class="overviewcard"><h3>최근 기대 득점</h3>${recent.length?`<svg class="chart" viewBox="0 0 330 155" role="img" aria-label="최근 경기 기대 득점, 실제 값은 최근 경기 표에 표시">${[0,trendMax/2,trendMax].map(v=>`<line x1="30" x2="310" y1="${125-v/trendMax*100}" y2="${125-v/trendMax*100}" stroke="#e0e6ee"/><text x="2" y="${129-v/trendMax*100}" fill="#536174" font-size="11">${v.toFixed(1)}</text>`).join('')}<polyline points="${line}" stroke="${c}" stroke-width="3" fill="none"/>${recent.map((m,i)=>`<circle cx="${35+i*65}" cy="${125-(m.home===id?m.hx:m.ax)/trendMax*100}" r="4" fill="${c}"><title>${m.date}: ${(m.home===id?m.hx:m.ax).toFixed(2)}</title></circle>`).join('')}<text x="30" y="150" fill="#536174" font-size="11">이전 경기</text><text x="255" y="150" fill="#536174" font-size="11">최근 경기</text></svg><p class="overviewcaption">${recent[0].date} ~ ${recent[recent.length-1].date}</p>`:'<p class="muted">선택 시즌의 기록 없음</p>'}</section></div>`}
'''
page=page.replace('function updateTeam(){',overview+'function updateTeam(){',1)
needle='<div class="timeline-title"><h3>시즌별 기록</h3>'
assert needle in page
page=page.replace(needle,'${teamOverview(id,ms)}<details class="recorddetails"><summary>시즌별 기록 · 전체 경기</summary>'+needle,1)
needle="${filtered.length?historyRows(id,filtered):'<p class=\"muted\">선택 조건의 경기가 없습니다.</p>'}`;"
assert needle in page
page=page.replace(needle,"${filtered.length?historyRows(id,filtered):'<p class=\"muted\">선택 조건의 경기가 없습니다.</p>'}</details>`;",1)
page=page.replace("V==='team')renderTeam()","V==='team')renderTeam()")
page=page.replace("team:'팀 분석'","team:'팀 종합 정보'")
with (out/'index.html').open('x',encoding='utf-8') as f:f.write(page)
test=(out.parent/'visualization-design-2026-10-06-v04/check.cjs').read_text(encoding='utf-8')
test=test.replace('/index-v02.html','/index.html').replace('Arsenal 과거 기록 보기','Arsenal 종합 정보 보기')
extra=r'''
test('team names share exact team route without nested links',()=>{let name=run('teamName("understat:83")');assert(name.includes('data-team="understat:83"'));assert(name.includes('>Arsenal</a>'));let combined=run('team("understat:83")');assert.strictEqual((combined.match(/<a /g)||[]).length,2);assert(!combined.match(/<a[^>]*>[^]*?<a[^>]*>[^]*?<\/a>[^]*?<\/a>/))});
test('team name click opens comprehensive overview',()=>{events.click({target:{closest(){return {dataset:{team:'understat:83'}}}},preventDefault(){}});assert.strictEqual(get('teamselect').value,'understat:83');assert.strictEqual(get('heading').textContent,'팀 종합 정보');const content=get('teamcontent').innerHTML;assert(content.includes('시즌 공격·수비'));assert(content.includes('최근 기대 득점'));assert(content.includes('다음 경기'));assert(content.includes('<details class="recorddetails">'));assert(!content.includes('<details class="recorddetails" open'))});
test('overview latest five and season win rate independently match data',()=>{get('season').value='2023/24';get('season').onchange();let ms=data.completed.filter(m=>m.season==='2023/24'&&(m.home==='understat:83'||m.away==='understat:83')).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));let wins=ms.filter(m=>m.home==='understat:83'?m.hg>m.ag:m.ag>m.hg).length;assert(get('teamcontent').innerHTML.includes((wins/ms.length*100).toFixed(1)+'%'));assert.strictEqual((get('teamcontent').innerHTML.match(/class="overviewdate">202[34]-/g)||[]).length,5)});
test('next fixtures are future scheduled records for selected team',()=>{let id='understat:83',ms=data.scheduled.filter(m=>(m.home===id||m.away===id)&&m.date>='2026-10-06').sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).slice(0,3);assert(ms.length>0);ms.forEach(m=>assert(get('teamcontent').innerHTML.includes(m.date)));assert(!run('teamOverview("understat:83",[])').includes('NaN'))});
'''
test=test.replace("fs.writeFileSync(__dirname+'/logic-check.json'",extra+"\nfs.writeFileSync(__dirname+'/logic-check.json'")
with (out/'check.cjs').open('x',encoding='utf-8') as f:f.write(test)
print('Created v05: team-name links, overview panels, collapsed history; previous versions preserved.')
